const ac = new AudioContext({sampleRate:48000});
window.reviewAudio = ac;
window.reviewTake = (hz=220, seconds=2, db=-20, pauses=[], card='usual', line='Who left this door open?') => {
  const rate=48000;
  const samples=new Float32Array(Math.round(rate*seconds));
  const gain=Math.sqrt(2)*10**(db/20);
  for(let i=0;i<samples.length;i++) {
    const time=i/rate;
    if(!pauses.some(p=>time>=p[0] && time<p[1])) samples[i]=gain*Math.sin(2*Math.PI*hz*time);
  }
  const result=__tool.analyze(samples,rate,line);
  if(!result) return null;
  const buffer=ac.createBuffer(1,samples.length,rate);
  buffer.copyToChannel(samples,0);
  __tool.shelfTake(result,buffer,{line,card});
  return __tool.state.takes.at(-1);
};
reviewTake();
reviewTake(330,1.2,-10,[],'mouse');
reviewTake(180,3,-25,[[1,1.5]],'wizard');
reviewTake(250,2,-20,[],'robot');reviewTake(190,2,-20,[],'boot');reviewTake(280,2,-20,[],'crown');

